use sailfish::TemplateSimple;

pub struct Case {
    pub name: &'static str,
    pub values: Vec<&'static str>,
    pub expected_len: usize,
    pub expected_hash: u64,
    pub render: fn(&[&str]) -> String,
    pub render_to: fn(&[&str], &mut sailfish::runtime::Buffer),
}

#[derive(TemplateSimple)]
#[template(path = "tiny.stpl")]
struct Tiny<'a> {
    v: &'a [&'a str],
}

fn render_tiny(v: &[&str]) -> String {
    Tiny { v }.render_once().unwrap()
}

fn render_tiny_to(v: &[&str], buf: &mut sailfish::runtime::Buffer) {
    Tiny { v }.render_once_to(buf).unwrap()
}

